makeCounter() call → new environment { count: 0 }
returned increment function ──► that count binding
call function → read count → write count → environment remains reachable

```javascript
function makeCounter() {
  let count = 0;
  return () => ++count;
}

const first = makeCounter();
const second = makeCounter();
console.log(first(), first());  // 1 2
console.log(second());          // 1
```

```javascript
function createAccount(opening = 0) {
  let balance = opening;
  return {
    deposit(amount) { if (amount > 0) balance += amount; },
    readBalance() { return balance; },
  };
}

const account = createAccount(10);
account.deposit(5);
console.log(account.readBalance()); // 15
```

```javascript
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log("var", i), 0);
}

for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log("let", j), 0);
}
// var: 3, 3, 3; let: 0, 1, 2
